WITH exploded AS (SELECT id, service, host, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS attr_key, attr_value), unpacked AS (SELECT id, service, host, latency_ms, attr_key, CAST((status_code & 4) != 0 AS INT) AS is_flagged, SHIFTRIGHT(status_code, 2) AS status_code_high FROM exploded), enriched AS (SELECT attr_key, is_flagged, COUNT(status_code_high) OVER (PARTITION BY attr_key) AS attr_key_count_status_code_high FROM unpacked), valid AS (SELECT *, LOWER(attr_key) AS attr_key_lower, ROUND(attr_key_count_status_code_high * 1.15, 2) AS adjusted_attr_key_count_status_code_high FROM enriched WHERE attr_key IN ('version', 'region')) SELECT attr_key, attr_key_lower, CASE WHEN attr_key RLIKE '^(version|region)$' THEN 'CORE' WHEN attr_key RLIKE '^(trace)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS attr_key_zone FROM valid
